-- Node: lp-coag-severe (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Severe Coagulopathy — High Risk","body":"**PLT <20,000, INR >2.0, or Active Anticoagulation**\n\n**Options:**\n\n1. **Correct coagulopathy first (if time allows):**\n   • Platelet transfusion (target >50,000)\n   • Vitamin K + PCC for warfarin (FFP slower)\n   • Idarucizumab for dabigatran\n   • 4F-PCC for Factor Xa inhibitors (andexanet alfa no longer marketed in the US)\n   • Wait for DOAC clearance (72h+)\n\n2. **Proceed despite risk (bacterial meningitis):**\n   • Discuss with attending\n   • Document risk-benefit discussion\n   • Use smallest needle, single attempt\n   • Close monitoring post-procedure\n\n3. **Empiric treatment without LP:**\n   • Treat based on clinical syndrome\n   • Blood cultures often yield organism\n   • LP when coagulation corrected\n\n**⚠️ In suspected bacterial meningitis:**\n• Mortality from untreated meningitis >> risk of spinal hematoma\n• Err on the side of treatment\n• Some experts proceed regardless of coagulation status [9][10]","citation":[9,10],"next":"lp-consent-prep","summary":"Severe coagulopathy: correct before LP — vit K + PCC for warfarin, platelets for thrombocytopenia, hold/reverse anticoagulants","safetyLevel":"warning"}'::jsonb
WHERE id = 'lp-coag-severe' AND tree_id = 'lumbar-puncture';

-- Node: mtp-anticoag (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Anticoagulated Patient in MTP","body":"**Immediate reversal required for massive hemorrhage:** [25]\n\n**Warfarin:**\n• [4-Factor PCC](#/drug/pcc-4factor/mtp) fixed 1000 IU (PROPER-3 [27]) or per institutional protocol; INR-tiered weight-based dosing as the institutional protocol (25-50 units/kg IV)\n• [Vitamin K](#/drug/vitamin-k/mtp) 10 mg IV over 30 min\n• Do NOT use FFP alone (volume-inefficient)\n\n**Direct Xa inhibitors (apixaban, rivaroxaban):**\n• 4-Factor PCC 25-50 units/kg (off-label for DOACs)\n• Andexanet alfa is no longer marketed in the US (where available outside the US only)\n\n**Dabigatran:**\n• [Idarucizumab](#/drug/idarucizumab/mtp) 5 g IV OR\n• 4-Factor PCC 25-50 units/kg (off-label for DOACs)\n• Hemodialysis if idarucizumab unavailable\n\n**Heparin/LMWH:**\n• [Protamine](#/drug/protamine/mtp) 1 mg per 100 units heparin (max 50 mg)\n• For LMWH: Protamine only ~50% effective\n\n**Antiplatelet agents:**\n• DDAVP 0.3 mcg/kg IV (improves platelet function)\n• Platelet transfusion — controversial (PATCH trial showed no benefit in ICH) [23]\n\nSee [Anticoagulant Reversal](#/tree/anticoag-reversal) for complete guidance.","citation":[23,25,27],"next":"mtp-special-pops"}'::jsonb
WHERE id = 'mtp-anticoag' AND tree_id = 'massive-transfusion';

-- Node: unwell-trauma-head (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Suspected Intracranial Injury — Image","body":"**Non-contrast head CT now** for any anticoagulated / antiplatelet elder with a fall or head strike, or any focal deficit / decreased GCS. — delayed bleeds occur; consider a period of observation ± repeat CT for anticoagulated patients even with an initially normal scan.\n\n**If bleed:** reverse anticoagulation emergently (per agent — e.g., 4-factor PCC + vitamin K for warfarin, 4-factor PCC for factor-Xa inhibitors (andexanet alfa no longer marketed in the US), idarucizumab for dabigatran), neurosurgery consult, BP control, admit.\n\n**Calibrate the delayed-bleed fear — it is real but small.** In a multicentre cohort of 1,596 anticoagulated patients with mild head injury (median age 84), delayed intracranial haemorrhage occurred in **1.8% on DOACs and 2.6% on vitamin K antagonists**, and **none required neurosurgery.** A meta-analysis of blunt head trauma on DOACs found pooled delayed ICH of **~2.4% (vs ~2.3% on warfarin)**, with **86% clinically inconsequential** and crude mortality **0.36%**. [24][25]\n\n**What that should change:** blanket 24-hour observation with routine repeat CT for every anticoagulated elder with a normal initial scan is **not** supported by these numbers. Target the repeat scan and the observation period at the patients who actually declare risk — **vomiting, new or evolving neurologic symptoms, loss of consciousness or amnesia, supratherapeutic INR (>3), concurrent antiplatelet therapy, or a poor social/observation situation at home.** A well, neurologically intact elder with a normal CT and a competent observer is a defensible discharge with explicit return precautions.","citation":[8,12,24,25],"recommendation":"Non-contrast head CT for anticoagulated fall / focal deficit; reverse anticoagulation emergently if bleed + neurosurgery; delayed ICH ~1.8-2.6% so target repeat imaging/observation selectively rather than universally.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'unwell-trauma-head' AND tree_id = 'nonspecific-unwell-elderly-hub';

-- Node: ugib-transfusion (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Transfusion Strategy","body":"**Restrictive Transfusion (Recommended):** [8]\n\n| Threshold | Hgb <7 g/dL |\n|-----------|-------------|\n| Target | 7-8 g/dL |\n| Exception | ACS: target >8 g/dL |\n\n**Why Restrictive?**\n• Excessive transfusion increases portal pressure\n• Worsens variceal bleeding\n• Villanueva: 45% mortality reduction with restrictive approach\n\n**Coagulation Targets:**\n• Platelets >50,000\n• Fibrinogen >150 mg/dL\n• INR: Consider reversal if supratherapeutic\n\n**Special Situations:**\n• **Massive bleeding:** Activate MTP, permissive hypotension\n• **On warfarin:** 4F-PCC if life-threatening; Vitamin K 10mg IV\n• **On DOAC:** Idarucizumab (dabigatran), 4F-PCC (Xa inhibitors; andexanet alfa no longer marketed in the US)","citation":[8],"next":"ugib-cirrhosis-check","summary":"Restrictive: Hgb <7 threshold (except ACS >8) — excessive transfusion increases portal pressure/worsens varices","safetyLevel":"warning"}'::jsonb
WHERE id = 'ugib-transfusion' AND tree_id = 'upper-gi-bleed';

